	/**
	 * Returns the script menu path.
	 * @return the script menu path
	 */
	public string[] getMenuPath() {
		parseHeader();
		if (menupath == null) {
			List<string> list = new();
			list.add("Scripts");
			foreach (string name in category) {
				list.add(name);
			}
			list.add(getNameNoExtension());
			menupath = list.toArray(new string[list.size()]);
		}
		return menupath;
	}

	private string getNameNoExtension() {
		string name = getName();
		int lastIndex = name.lastIndexOf(".");
		if (lastIndex > 0) {
			name = name.substring(0, lastIndex);
		}
		return name;
	}

	/**
	 * Returns the script menu path as a string.
	 * For example,{@literal "Path1->Path2->Path3"}.
	 * @return the script menu path as a string
	 */
	public string getMenuPathAsString() {
		string menuPath = "";
		string[] menuPathArr = getMenuPath();
		foreach (string path in menuPathArr) {
			if (menuPath.length() > 0) {
				menuPath = menuPath + "->";
			}
			menuPath = menuPath + path;
		}
		return menuPath;
	}

